import torch

@torch.compile
def f(x):
    # x is a compiled-region input; v is a view aliased with x
    v = x[:, 0:4]
    v.add_(1.0)                      # in-place on the view -> mutates the underlying storage of x
    return x.sum()

x = torch.zeros(8, 8, device="cuda")
y = f(x)
# After the call, x reflects the +1 written into columns 0..3.
